  WHIRLPOOL_ROUNDS*: int = 10
  WHIRLPOOL_HASH_SIZE*: int = 32

type
  Version* = enum
    C0 = 0
    C1 = 1
    Standard = 2

  WhirlpoolGenericCtx*[hashSize, blockSize: static int, version: static Version] = object
    state*: array[8, uint64]
    buffer*: array[blockSize, uint8]
    index*: int
    length*: uint64

  WhirlpoolCtx* = WhirlpoolGenericCtx[64, 64, Standard]

template whirlpoolTransform[K, B: static int, C: static Version](ctx: var WhirlpoolGenericCtx[K, B, C], chunk: slicearray[64, uint8]): void =
  var message: array[8, uint64]
  var key: array[8, uint64]
  var state: array[8, uint64]
  var temp: array[8, uint64]

  decodeBE(chunk, message.toSliceArray(0, 7))
  copyMem(addr key[0], addr ctx.state[0], 64)
  for i in static(0 ..< 8):
    state[i] = message[i] xor key[i]

  const RC = when C == C0: RC0 elif C == C1: RC1 else: RCST
  const Table = when C == C0: Table0 elif C == C1: Table1 else: TableST

  for r in static(1 .. WHIRLPOOL_ROUNDS):
    for i in static(0 ..< 8):
      temp[i] = Table[0][((key[(i + 0) mod 8] shr 56) and 0xFF'u8)] xor
                Table[1][((key[(i + 7) mod 8] shr 48) and 0xFF'u8)] xor
                Table[2][((key[(i + 6) mod 8] shr 40) and 0xFF'u8)] xor
                Table[3][((key[(i + 5) mod 8] shr 32) and 0xFF'u8)] xor
                Table[4][((key[(i + 4) mod 8] shr 24) and 0xFF'u8)] xor
                Table[5][((key[(i + 3) mod 8] shr 16) and 0xFF'u8)] xor
                Table[6][((key[(i + 2) mod 8] shr  8) and 0xFF'u8)] xor
                Table[7][((key[(i + 1) mod 8]       ) and 0xFF'u8)]
    temp[0] = temp[0] xor RC[r]
    key = temp

    for i in static(0 ..< 8):
      temp[i] = Table[0][((state[(i + 0) mod 8] shr 56) and 0xFF'u8)] xor
                Table[1][((state[(i + 7) mod 8] shr 48) and 0xFF'u8)] xor
                Table[2][((state[(i + 6) mod 8] shr 40) and 0xFF'u8)] xor
                Table[3][((state[(i + 5) mod 8] shr 32) and 0xFF'u8)] xor
                Table[4][((state[(i + 4) mod 8] shr 24) and 0xFF'u8)] xor
                Table[5][((state[(i + 3) mod 8] shr 16) and 0xFF'u8)] xor
                Table[6][((state[(i + 2) mod 8] shr  8) and 0xFF'u8)] xor
                Table[7][((state[(i + 1) mod 8]       ) and 0xFF'u8)] xor key[i]
    state = temp

  for i in static(0 ..< 8):
    ctx.state[i] = ctx.state[i] xor state[i] xor message[i]

template whirlpoolInitC[K, B: static int, C: static Version](ctx: var WhirlpoolGenericCtx[K, B, C]): void =
  when K != 64 or B != 64:
    {.fatal: "WhirlpoolCtx requires hashSize 64 and blockSize 64".}
  zeroMem(addr ctx.state, 64)
  zeroMem(addr ctx.buffer, B)
  ctx.index = 0
  ctx.length = 0'u64

template whirlpoolInputC[K, B: static int, C: static Version](ctx: var WhirlpoolGenericCtx[K, B, C], input: openArray[uint8]): void =
  var check: bool = true
  let inputLen: int = input.len

  if inputLen <= 0: check = false

  if check:
    var index: int = ctx.index
    ctx.length += uint64(inputLen)

    let left: int = B - index
    var position: int = 0

    if inputLen >= left:
      if left > 0:
        copyMem(addr ctx.buffer[index], addr input[position], left)
      whirlpoolTransform(ctx, ctx.buffer.toSliceArray(0, B - 1))
      position = left
      index = 0

      while position + 64 <= inputLen:
        whirlpoolTransform(ctx, input.toSliceArray(position, position + B - 1, B))
        position += B

    let remain: int = inputLen - position
    if remain > 0:
      copyMem(addr ctx.buffer[index], addr input[position], remain)
      index += remain

    ctx.index = index

template whirlpoolFinalC[K, B: static int, C: static Version](ctx: var WhirlpoolGenericCtx[K, B, C]): array[K, uint8] =
  var output: array[K, uint8]

  var index: int = ctx.index
  ctx.buffer[index] = 0x80'u8
  index.inc

  let padLen: int = if index <= 32: 56 - index else: 64 - index

  if index <= 32:
    zeroMem(addr ctx.buffer[index], padLen)
  else:
    if padLen > 0:
      zeroMem(addr ctx.buffer[index], padLen)
    whirlpoolTransform(ctx, ctx.buffer.toSliceArray(0, B - 1))
    zeroMem(addr ctx.buffer[0], 56)

  ctx.length = ctx.length shl 3
  toBytesBE(ctx.length, ctx.buffer.toSliceArray(56, B - 1))

  whirlpoolTransform(ctx, ctx.buffer.toSliceArray(0, B - 1))

  encodeBE(ctx.state.toSliceArray(0, K div 8 - 1), output.toSliceArray(0, K - 1))

  output

# export wrappers
when defined(templateOpt):
  template whirlpoolInit*(ctx: var WhirlpoolCtx): void = whirlpoolInitC(ctx)
  template whirlpoolInput*(ctx: var WhirlpoolCtx, input: openArray[uint8]): void = whirlpoolInputC(ctx, input)
  template whirlpoolFinal*(ctx: var WhirlpoolCtx): array[64, uint8] = whirlpoolFinalC(ctx)

  when Native:
    template whirlpoolInit*(ctx: ptr WhirlpoolCtx): void = whirlpoolInitC(ctx[])
    template whirlpoolInput*(ctx: ptr WhirlpoolCtx, input: ptr UncheckedArray[uint8], inputLen: int): void = whirlpoolInputC(ctx[], input.toOpenArray(0, inputLen - 1))
    template whirlpoolFinal*(ctx: ptr WhirlpoolCtx, output: ptr array[64, uint8]): void = output[] = whirlpoolFinalC(ctx[])

else:
  when Native:
    proc whirlpoolInit*(ctx: var WhirlpoolCtx): void = whirlpoolInitC(ctx)
    proc whirlpoolInput*(ctx: var WhirlpoolCtx, input: openArray[uint8]): void = whirlpoolInputC(ctx, input)
    proc whirlpoolFinal*(ctx: var WhirlpoolCtx): array[64, uint8] = whirlpoolFinalC(ctx)

  when defined(c) or defined(objc):
    proc whirlpoolInit*(ctx: ptr WhirlpoolCtx): void {.exportc: "whirlpoolInit".} = whirlpoolInitC(ctx[])
    proc whirlpoolInput*(ctx: ptr WhirlpoolCtx, input: ptr UncheckedArray[uint8], inputLen: int): void {.exportc: "whirlpoolInput".} = whirlpoolInputC(ctx[], input.toOpenArray(0, inputLen - 1))
    proc whirlpoolFinal*(ctx: ptr WhirlpoolCtx, output: ptr array[64, uint8]): void {.exportc: "whirlpoolFinal".} = output[] = whirlpoolFinalC(ctx[])

  elif defined(cpp):
    proc whirlpoolInit*(ctx: ptr WhirlpoolCtx): void {.exportcpp: "whirlpoolInit".} = whirlpoolInitC(ctx[])
    proc whirlpoolInput*(ctx: ptr WhirlpoolCtx, input: ptr UncheckedArray[uint8], inputLen: int): void {.exportcpp: "whirlpoolInput".} = whirlpoolInputC(ctx[], input.toOpenArray(0, inputLen - 1))
    proc whirlpoolFinal*(ctx: ptr WhirlpoolCtx, output: ptr array[64, uint8]): void {.exportcpp: "whirlpoolFinal".} = output[] = whirlpoolFinalC(ctx[])
